BEGIN;
CREATE SCHEMA IF NOT EXISTS notify;
CREATE TABLE IF NOT EXISTS notify.chats(chat_id text PRIMARY KEY, paused boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS notify.follows(chat_id text NOT NULL REFERENCES notify.chats ON DELETE CASCADE,wallet text NOT NULL,followed_at timestamptz NOT NULL,PRIMARY KEY(chat_id,wallet));
CREATE INDEX IF NOT EXISTS follows_wallet_idx ON notify.follows(wallet);
CREATE TABLE IF NOT EXISTS notify.trades(signature text NOT NULL,event_index integer NOT NULL CHECK(event_index>=0),slot bigint NOT NULL,wallet text NOT NULL,mint text NOT NULL,is_buy boolean NOT NULL,sol_lamports numeric(20,0) NOT NULL CHECK(sol_lamports>=0),quote_mint text NOT NULL,event_time timestamptz NOT NULL,seen_at timestamptz NOT NULL,PRIMARY KEY(signature,event_index));
CREATE INDEX IF NOT EXISTS trades_time_idx ON notify.trades(event_time);
CREATE INDEX IF NOT EXISTS trades_seen_idx ON notify.trades(seen_at);
CREATE TABLE IF NOT EXISTS notify.deliveries(chat_id text NOT NULL REFERENCES notify.chats,signature text NOT NULL,event_index integer NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','sending','sent','unknown','failed','cancelled')),not_before timestamptz NOT NULL,attempted_at timestamptz,error_code text,message_id bigint,PRIMARY KEY(chat_id,signature,event_index),FOREIGN KEY(signature,event_index) REFERENCES notify.trades ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS deliveries_pending_idx ON notify.deliveries(state,not_before);
CREATE TABLE IF NOT EXISTS notify.rates(chat_id text NOT NULL REFERENCES notify.chats,scope text NOT NULL,next_at timestamptz NOT NULL,PRIMARY KEY(chat_id,scope));
CREATE TABLE IF NOT EXISTS notify.runtime(id integer PRIMARY KEY CHECK(id=1),telegram_offset bigint NOT NULL DEFAULT 0,heartbeat timestamptz,info jsonb NOT NULL DEFAULT '{}');
INSERT INTO notify.runtime(id) VALUES(1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS notify.commands(update_id bigint PRIMARY KEY,processed_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS notify.gaps(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,reason text NOT NULL,start_slot bigint,end_slot bigint,recorded_at timestamptz NOT NULL);
ALTER TABLE notify.chats ENABLE ROW LEVEL SECURITY;
ALTER TABLE notify.follows ENABLE ROW LEVEL SECURITY;
ALTER TABLE notify.trades ENABLE ROW LEVEL SECURITY;
ALTER TABLE notify.deliveries ENABLE ROW LEVEL SECURITY;
ALTER TABLE notify.rates ENABLE ROW LEVEL SECURITY;
ALTER TABLE notify.runtime ENABLE ROW LEVEL SECURITY;
ALTER TABLE notify.commands ENABLE ROW LEVEL SECURITY;
ALTER TABLE notify.gaps ENABLE ROW LEVEL SECURITY;
COMMIT;
